// @generated by:gauntlet run:godseye-local-broker
import { randomUUID } from "node:crypto";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { isAbsolute, join, relative, resolve } from "node:path";
import { AccessBroker, FoundationEngine } from "@godseye/core";
import { openStore } from "@godseye/store";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { type AccessFixture, accessFixture, currentSlot, prepareAccess } from "./access-helpers.js";

describe("controlled static rotation and uncertainty", () => {
  let fixture: AccessFixture;
  beforeEach(async () => {
    fixture = await accessFixture();
  });
  afterEach(async () => {
    await fixture?.store.close();
  });

  it("T-AC-17 T08 preserves active access while a replacement is staged and commits only qualified transition evidence", async () => {
    const access = await prepareAccess(fixture);
    const replacement = randomUUID();
    await fixture.broker.stage(
      fixture.freshOwner(),
      { slotId: access.slot.id, expectedRevision: access.slot.revision },
      replacement,
      randomUUID(),
    );
    let deliveredPrior = false;
    await fixture.broker.consumeStatic(access.proof, access.slot.id, (value) => {
      deliveredPrior = value === access.value;
    });
    expect(deliveredPrior).toBe(true);
    const staged = await currentSlot(fixture, access.slot.id);
    expect(staged).toMatchObject({ state: "staged", activeVersion: 1, stagedVersion: 2 });
    const operation = await fixture.broker.activate(
      fixture.freshOwner(),
      staged.id,
      fixture.transition.adapter.id,
      staged.revision,
      randomUUID(),
    );
    expect(operation.state).toBe("succeeded");
    let deliveredNext = false;
    await fixture.broker.consumeStatic(access.proof, access.slot.id, (value) => {
      deliveredNext = value === replacement;
    });
    expect(deliveredNext).toBe(true);
    expect(await currentSlot(fixture, staged.id)).toMatchObject({
      state: "active",
      activeVersion: 2,
      stagedVersion: null,
    });
  });

  it("T-AC-17 T08 refuses activation without a qualified real-target transition adapter", async () => {
    const access = await prepareAccess(fixture, { activate: false });
    const restricted = new AccessBroker(fixture.store, {
      ...fixture.brokerOptions,
      transitions: [],
    });
    await expect(
      restricted.activate(
        fixture.freshOwner(),
        access.slot.id,
        fixture.transition.adapter.id,
        access.slot.revision,
        randomUUID(),
      ),
    ).rejects.toMatchObject({ status: 503 });
    expect(await currentSlot(fixture, access.slot.id)).toMatchObject({
      activeVersion: null,
      state: "staged",
      stagedVersion: 1,
    });
  });

  for (const interruption of ["identity revocation", "activation epoch advance"] as const) {
    it(`T-AC-17 T22 prevents qualified adapter dispatch after ${interruption} during material lookup`, async () => {
      const access = await prepareAccess(fixture, { activate: false });
      let interrupted = false;
      fixture.materialProvider.beforeRead = async () => {
        if (interrupted) return;
        interrupted = true;
        if (interruption === "identity revocation") {
          await fixture.broker.revokeIdentity(
            fixture.freshOwner(),
            access.identity.id,
            access.identity.revision,
            randomUUID(),
          );
        } else {
          await fixture.engine.advanceEpoch(
            fixture.freshOwner(),
            fixture.development.id,
            randomUUID(),
          );
        }
      };
      // Authority loss may reject the caller; neither response form may dispatch or mark success.
      const [response] = await Promise.allSettled([
        fixture.broker.activate(
          fixture.freshOwner(),
          access.slot.id,
          fixture.transition.adapter.id,
          access.slot.revision,
          randomUUID(),
        ),
      ]);
      expect(interrupted).toBe(true);
      expect(fixture.transition.calls).toHaveLength(0);
      expect(response?.status === "rejected" || response?.value.state === "unknown").toBe(true);
      expect(
        (await fixture.broker.overview(fixture.freshOwner())).operations.find(
          (row) => row.slotId === access.slot.id && row.kind === "activate",
        )?.state,
      ).toBe("unknown");
      expect((await currentSlot(fixture, access.slot.id)).activeVersion).toBeNull();
    });
  }

  it("T-AC-17 T08 preserves prior availability after a definitive qualified readiness failure", async () => {
    const access = await prepareAccess(fixture);
    await fixture.broker.stage(
      fixture.freshOwner(),
      { slotId: access.slot.id, expectedRevision: access.slot.revision },
      randomUUID(),
      randomUUID(),
    );
    const staged = await currentSlot(fixture, access.slot.id);
    fixture.transition.outcome((context) => ({
      status: "failed",
      operationId: context.operationId,
      candidateVersion: context.candidateVersion,
      previousAccessPreserved: true,
      phase: "readiness",
      evidence: "fixture:old-target-verified-unchanged",
    }));
    const result = await fixture.broker.activate(
      fixture.freshOwner(),
      staged.id,
      fixture.transition.adapter.id,
      staged.revision,
      randomUUID(),
    );
    expect(result.state).toBe("failed");
    let delivered = false;
    await fixture.broker.consumeStatic(access.proof, access.slot.id, (value) => {
      delivered = value === access.value;
    });
    expect(delivered).toBe(true);
    expect(await currentSlot(fixture, staged.id)).toMatchObject({
      state: "staged",
      activeVersion: 1,
      stagedVersion: 2,
    });
  });

  it("T-AC-17 T37 reconciles a lost staging receipt on replay without appending another provider version", async () => {
    const access = await prepareAccess(fixture);
    const key = randomUUID();
    const replacement = randomUUID();
    const input = { slotId: access.slot.id, expectedRevision: access.slot.revision };
    fixture.materialProvider.failAfterWrite = true;
    const uncertain = await fixture.broker.stage(fixture.freshOwner(), input, replacement, key);
    expect(uncertain.state).toBe("unknown");
    let retained = false;
    await fixture.broker.consumeStatic(access.proof, access.slot.id, (value) => {
      retained = value === access.value;
    });
    expect(retained).toBe(true);
    const writes = fixture.materialProvider.writes;
    const reconciled = await fixture.broker.stage(fixture.freshOwner(), input, replacement, key);
    expect(reconciled).toMatchObject({ id: uncertain.id, state: "succeeded", candidateVersion: 2 });
    expect(fixture.materialProvider.writes).toBe(writes);
    await expect(
      fixture.broker.stage(fixture.freshOwner(), input, randomUUID(), key),
    ).rejects.toMatchObject({ status: 409 });
  });

  it("T-AC-17 T37 admits only one concurrent staging mutation for identical replay", async () => {
    const access = await prepareAccess(fixture);
    const key = randomUUID();
    const replacement = randomUUID();
    const input = { slotId: access.slot.id, expectedRevision: access.slot.revision };
    const before = fixture.materialProvider.writes;
    const results = await Promise.all([
      fixture.broker.stage(fixture.freshOwner(), input, replacement, key),
      fixture.broker.stage(fixture.freshOwner(), input, replacement, key),
    ]);
    expect(results[0]?.id).toBe(results[1]?.id);
    expect(fixture.materialProvider.writes - before).toBe(1);
    expect(
      (await fixture.broker.reconcile(fixture.freshOwner(), results[0]?.id ?? "", randomUUID()))
        .state,
    ).toBe("succeeded");
  });

  it("T-AC-17 T23 keeps an ambiguous upstream transition visible and reconciles without repeating it", async () => {
    const access = await prepareAccess(fixture);
    const replacement = randomUUID();
    await fixture.broker.stage(
      fixture.freshOwner(),
      { slotId: access.slot.id, expectedRevision: access.slot.revision },
      replacement,
      randomUUID(),
    );
    const staged = await currentSlot(fixture, access.slot.id);
    fixture.transition.outcome(() => ({ status: "unknown" }));
    const key = randomUUID();
    const uncertain = await fixture.broker.activate(
      fixture.freshOwner(),
      staged.id,
      fixture.transition.adapter.id,
      staged.revision,
      key,
    );
    expect(uncertain.state).toBe("unknown");
    let delivered = false;
    await expect(
      fixture.broker.consumeStatic(access.proof, access.slot.id, () => {
        delivered = true;
      }),
    ).rejects.toMatchObject({ code: "RECONCILIATION_REQUIRED" });
    expect(delivered).toBe(false);
    const calls = fixture.transition.calls.length;
    fixture.transition.outcome((context) => ({
      status: "succeeded",
      operationId: context.operationId,
      candidateVersion: context.candidateVersion,
      transitioned: true,
      oldAccessRevoked: true,
      evidence: "fixture:confirmed-target-and-revoke",
    }));
    expect(
      (
        await fixture.broker.activate(
          fixture.freshOwner(),
          staged.id,
          fixture.transition.adapter.id,
          staged.revision,
          key,
        )
      ).state,
    ).toBe("succeeded");
    expect(fixture.transition.calls.length).toBe(calls);
    expect((await currentSlot(fixture, staged.id)).activeVersion).toBe(2);
  });

  it("T-AC-17 T22 rejects foreign and blank transition receipts instead of declaring upstream revocation", async () => {
    const access = await prepareAccess(fixture, { activate: false });
    fixture.transition.outcome((context) => ({
      status: "succeeded",
      operationId: randomUUID(),
      candidateVersion: context.candidateVersion,
      transitioned: true,
      oldAccessRevoked: true,
      evidence: "fixture:foreign-receipt",
    }));
    const operation = await fixture.broker.activate(
      fixture.freshOwner(),
      access.slot.id,
      fixture.transition.adapter.id,
      access.slot.revision,
      randomUUID(),
    );
    expect(operation.state).toBe("unknown");
    fixture.transition.outcome((context) => ({
      status: "succeeded",
      operationId: context.operationId,
      candidateVersion: context.candidateVersion,
      transitioned: true,
      oldAccessRevoked: true,
      evidence: "   ",
    }));
    expect(
      (await fixture.broker.reconcile(fixture.freshOwner(), operation.id, randomUUID())).state,
    ).toBe("unknown");
    expect((await currentSlot(fixture, access.slot.id)).activeVersion).toBeNull();
  });

  it("T-AC-17 T08 blocks new proof issuance, staging and rotation while the provider is sealed", async () => {
    const access = await prepareAccess(fixture);
    const mounted = access.value;
    fixture.materialProvider.state = "sealed";
    for (const work of [
      () =>
        fixture.broker.issueProof(
          fixture.freshOwner(),
          access.identity.id,
          access.identity.revision,
          randomUUID(),
          () => undefined,
        ),
      () =>
        fixture.broker.stage(
          fixture.freshOwner(),
          { slotId: access.slot.id, expectedRevision: access.slot.revision },
          randomUUID(),
          randomUUID(),
        ),
      () =>
        fixture.broker.activate(
          fixture.freshOwner(),
          access.slot.id,
          fixture.transition.adapter.id,
          access.slot.revision,
          randomUUID(),
        ),
      () => fixture.broker.consumeStatic(access.proof, access.slot.id, () => undefined),
    ])
      await expect(work()).rejects.toMatchObject({ code: "CAPABILITY_UNAVAILABLE" });
    expect((await fixture.broker.overview(fixture.freshOwner())).provider.state).toBe("sealed");
    expect(mounted === access.value).toBe(true);
    fixture.materialProvider.state = "ready";
    let delivered = false;
    await fixture.broker.consumeStatic(access.proof, access.slot.id, (value) => {
      delivered = value === mounted;
    });
    expect(delivered).toBe(true);
  });

  it("T-AC-17 T31 reopens durable intentions and reconciles an unknown provider write without resubmission", async () => {
    const directory = await mkdtemp(join(tmpdir(), "godseye-access-restart-"));
    const persistent = await accessFixture({ dataDir: join(directory, "control") });
    let reopened: Awaited<ReturnType<typeof openStore>> | undefined;
    let closed = false;
    try {
      const access = await prepareAccess(persistent);
      const input = { slotId: access.slot.id, expectedRevision: access.slot.revision };
      const replacement = randomUUID();
      const key = randomUUID();
      persistent.materialProvider.failAfterWrite = true;
      const uncertain = await persistent.broker.stage(
        persistent.freshOwner(),
        input,
        replacement,
        key,
      );
      expect(uncertain.state).toBe("unknown");
      const writes = persistent.materialProvider.writes;
      await persistent.store.close();
      closed = true;
      reopened = await openStore({ dataDir: join(directory, "control") });
      const engine = new FoundationEngine(reopened, { now: persistent.clock.now });
      const broker = new AccessBroker(reopened, {
        ...persistent.brokerOptions,
        foundation: engine,
      });
      const recovered = await broker.stage(persistent.freshOwner(), input, replacement, key);
      expect(recovered).toMatchObject({ id: uncertain.id, state: "succeeded" });
      expect(persistent.materialProvider.writes).toBe(writes);
      let delivered = false;
      await broker.consumeStatic(access.proof, access.slot.id, (value) => {
        delivered = value === access.value;
      });
      expect(delivered).toBe(true);
    } finally {
      await reopened?.close();
      if (!closed) await persistent.store.close();
      const nested = relative(resolve(tmpdir()), resolve(directory));
      if (nested.startsWith("godseye-access-restart-") && !isAbsolute(nested))
        await rm(directory, { recursive: true, force: true, maxRetries: 5, retryDelay: 100 });
    }
  }, 60_000);
});
